ALTER TABLE stop_factors.stop_factor_group ADD COLUMN name VARCHAR(255);
UPDATE stop_factors.stop_factor_group g
SET name = CASE WHEN (SELECT count(*) FROM stop_factors.stop_factor f WHERE f.group_id = g.id) = 1
                THEN (SELECT f.name FROM stop_factors.stop_factor f
                      WHERE f.group_id = g.id ORDER BY f.order_number LIMIT 1)
                ELSE (SELECT m.title FROM stop_factors.stop_factor f
                      JOIN stop_factors.stop_factor_metric m ON m.id = f.metric_id
                      WHERE f.group_id = g.id ORDER BY f.order_number LIMIT 1) END;
ALTER TABLE stop_factors.stop_factor_group ALTER COLUMN name SET NOT NULL;
